SELECT id, log_ts, context['region'] AS region, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs WHERE TO_DATE(log_ts) >= '2024-10-18'
